// Pull the uploaded CSV file's text out of the binary payload, regardless of
// which binary key the browser used. Falls back to a JSON body with csv_text
// (handy for the manual/demo trigger or API clients).
const item = $input.first();
let csvText = null;
let filename = null;

if (item.binary) {
  const key = Object.keys(item.binary)[0];
  if (key) {
    const bin = item.binary[key];
    filename = bin.fileName || null;
    csvText = Buffer.from(bin.data, 'base64').toString('utf-8');
  }
}

if (!csvText && item.json) {
  if (item.json.csv_text) csvText = item.json.csv_text;
  else if (item.json.body && item.json.body.csv_text) csvText = item.json.body.csv_text;
}

if (!csvText) {
  throw new Error('No CSV file found. Upload a file field or send {"csv_text": "..."}.');
}

return [{ json: { csv_text: csvText, filename: filename } }];
